// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Complex64Array } from '@stdlib/types/array';
import { Complex64 } from '@stdlib/types/complex';

/**
* Interface describing `cdotu`.
*/
interface Routine {
	/**
	* Calculates the dot product of vectors `zx` and `zy`.
	*
	* @param N - number of indexed elements
	* @param zx - first input array
	* @param strideX - `zx` stride length
	* @param zy - second input array
	* @param strideY - `zy` stride length
	* @returns dot product
	*
	* @example
	* var Complex64Array = require( '@stdlib/array/complex64' );
	* var real = require( '@stdlib/complex/float32/real' );
	* var imag = require( '@stdlib/complex/float32/imag' );
	*
	* var zx = new Complex64Array( [ 4.0, 2.0, -3.0, 5.0, -1.0, 7.0 ] );
	* var zy = new Complex64Array( [ 2.0, 6.0, -1.0, -4.0, 8.0, 9.0 ] );
	*
	* var z = cdotu( 3, zx, 1, zy, 1 );
	* // returns <Complex64>
	*
	* var re = real( z );
	* // returns -52.0
	*
	* var im = imag( z );
	* // returns 82.0
	*/
	( N: number, zx: Complex64Array, strideX: number, zy: Complex64Array, strideY: number ): Complex64;

	/**
	* Calculates the dot product of vectors `zx` and `zy` using alternative indexing semantics.
	*
	* @param N - number of indexed elements
	* @param zx - first input array
	* @param strideX - `zx` stride length
	* @param offsetX - starting index for `zx`
	* @param zy - second input array
	* @param strideY - `zy` stride length
	* @param offsetY - starting index for `zy`
	* @returns dot product
	*
	* @example
	* var Complex64Array = require( '@stdlib/array/complex64' );
	* var real = require( '@stdlib/complex/float32/real' );
	* var imag = require( '@stdlib/complex/float32/imag' );
	*
	* var zx = new Complex64Array( [ 4.0, 2.0, -3.0, 5.0, -1.0, 7.0 ] );
	* var zy = new Complex64Array( [ 2.0, 6.0, -1.0, -4.0, 8.0, 9.0 ] );
	*
	* var z = cdotu.ndarray( 3, zx, 1, 0, zy, 1, 0 );
	* // returns <Complex64>
	*
	* var re = real( z );
	* // returns -52.0
	*
	* var im = imag( z );
	* // returns 82.0
	*/
	ndarray( N: number, zx: Complex64Array, strideX: number, offsetX: number, zy: Complex64Array, strideY: number, offsetY: number ): Complex64;
}

/**
* Computes the dot product of two single-precision complex floating-point vectors.
*
* @param N - number of indexed elements
* @param zx - first input array
* @param strideX - `zx` stride length
* @param zy - second input array
* @param strideY - `zy` stride length
* @returns dot product
*
* @example
* var Complex64Array = require( '@stdlib/array/complex64' );
* var real = require( '@stdlib/complex/float32/real' );
* var imag = require( '@stdlib/complex/float32/imag' );
*
* var zx = new Complex64Array( [ 4.0, 2.0, -3.0, 5.0, -1.0, 7.0 ] );
* var zy = new Complex64Array( [ 2.0, 6.0, -1.0, -4.0, 8.0, 9.0 ] );
*
* var z = cdotu( 3, zx, 1, zy, 1 );
* // returns <Complex64>
*
* var re = real( z );
* // returns -52.0
*
* var im = imag( z );
* // returns 82.0
*
* @example
* var Complex64Array = require( '@stdlib/array/complex64' );
* var real = require( '@stdlib/complex/float32/real' );
* var imag = require( '@stdlib/complex/float32/imag' );
*
* var zx = new Complex64Array( [ 4.0, 2.0, -3.0, 5.0, -1.0, 7.0 ] );
* var zy = new Complex64Array( [ 2.0, 6.0, -1.0, -4.0, 8.0, 9.0 ] );
*
* var z = cdotu.ndarray( 3, zx, 1, 0, zy, 1, 0 );
* // returns <Complex64>
*
* var re = real( z );
* // returns -52.0
*
* var im = imag( z );
* // returns 82.0
*/
declare var cdotu: Routine;


// EXPORTS //

export = cdotu;
